function glowTexture(){const n=32,data=new Uint8Array(n*n*4);for(let y=0;y<n;y++)for(let x=0;x<n;x++){const r=Math.hypot((x+.5)/n*2-1,(y+.5)/n*2-1),i=(y*n+x)*4;data[i]=data[i+1]=data[i+2]=255;data[i+3]=Math.round(Math.max(0,1-r)**2.4*255);}const tex=new T.DataTexture(data,n,n);tex.needsUpdate=true;return tex;}
export function fitEvolutionCamera(frame,bounds,aspect=1){const position={...frame.camera},target={x:0,y:frame.targetY,z:0},pad=bounds.height*.08+.06,box={min:{x:-bounds.halfWidth-pad,y:-pad,z:-bounds.halfDepth-pad},max:{x:bounds.halfWidth+pad,y:bounds.height+frame.lift+pad,z:bounds.halfDepth+pad}};
 for(let i=0;i<40&&!framesBoxes(position,target,[box],frame.fov,aspect,.86);i++){position.x*=1.06;position.z*=1.06;position.y=target.y+(position.y-target.y)*1.06;}return position;
}
function formBounds(form){if(form.bodyBounds)return{...form.bodyBounds,height:FORM_HEIGHTS[form.level]};form.model.updateMatrixWorld(true);const b=new T.Box3().setFromObject(form.model),s=b.getSize(new T.Vector3());return{halfWidth:Math.max(s.x,s.z)/2,halfDepth:Math.max(s.x,s.z)/2,height:Math.max(s.y,FORM_HEIGHTS[form.level])};}
export class EvolutionStage{
 constructor(world,from,to,oldForm,newForm,{onFrame=()=>{},reduced=false}={}){
  this.palette=partnerInfo(world.partner);this.element=evolutionElement(this.palette.element);this.world=world;this.from=from;this.to=to;this.oldForm=oldForm;this.newForm=newForm;this.onFrame=onFrame;this.reduced=reduced;this.time=0;this.resolved=false;this.disposed=false;
  const a=formBounds(oldForm),b=formBounds(newForm);this.bounds={halfWidth:Math.max(a.halfWidth,b.halfWidth),halfDepth:Math.max(a.halfDepth,b.halfDepth),height:Math.max(a.height,b.height)};this.height=this.bounds.height;this.size=Math.max(.65,this.height*.72);this.root=new T.Group();this.root.position.set(world.nav.player.x,world.nav.y||0,world.nav.player.z);this.root.rotation.y=world.creature.rotation.y+(world.locomotion?.forwardYaw||0);world.scene.add(this.root);
  this.saved={land:world.land.visible,effects:world.effects.visible,creature:world.creature.visible,rival:world.rival.visible,background:world.scene.background.clone(),fog:world.scene.fog,exposure:world.renderer.toneMappingExposure,sky:world.sky?.visible,view:world.camera.view?{...world.camera.view}:null,viewShift:world.viewShift};world.land.visible=false;world.effects.visible=false;world.creature.visible=false;world.rival.visible=false;if(world.sky)world.sky.visible=false;world.scene.fog=null;world.camera.clearViewOffset();
  this.oldRoot=new T.Group();this.newRoot=new T.Group();this.oldRoot.add(oldForm.model);this.newRoot.add(newForm.model);this.oldRoot.rotation.y=-(oldForm.forwardYaw||0);this.newRoot.rotation.y=-(newForm.forwardYaw||0);this.root.add(this.oldRoot,this.newRoot);this.oldPose=new EvolutionPose(oldForm);this.newPose=new EvolutionPose(newForm);
  this.originalMaterials=new Map();this.originalShadows=new Map();for(const form of[oldForm,newForm])form.model.traverse(o=>{if(o.isMesh){this.originalMaterials.set(o,o.material);this.originalShadows.set(o,[o.castShadow,o.receiveShadow]);o.castShadow=false;o.receiveShadow=false;}});this.silhouette=new T.MeshBasicMaterial({color:this.palette.color,toneMapped:false});
  this.texture=glowTexture();this.floor=new T.Mesh(new T.CircleGeometry(this.size*5,48),new T.MeshBasicMaterial({color:'#17323a',side:T.DoubleSide}));this.floor.rotation.x=-Math.PI/2;this.floor.position.y=-.025;this.root.add(this.floor);
  this.signature=new EvolutionEffects(this.element,this.palette,this.height,this.size,{reduced});this.root.add(this.signature.root);this.rings=this.signature.floor;this.ribbons=this.signature.ribbons;this.glows=[];for(let i=0;i<2;i++){const sprite=new T.Sprite(new T.SpriteMaterial({map:this.texture,color:i?this.palette.accent:'#fff2d6',transparent:true,opacity:0,depthWrite:false,blending:T.AdditiveBlending,toneMapped:false}));sprite.position.y=this.height*(i?.35:.65);this.root.add(sprite);this.glows.push(sprite);}
  this.light=new T.PointLight(this.palette.color,0,this.height*9,1.5);this.light.position.y=this.height*.65;this.root.add(this.light);this.eye=new T.Vector3();this.target=new T.Vector3();this.axis=new T.Vector3(0,1,0);this.background=new T.Color();this.promise=new Promise(resolve=>this.resolve=resolve);this.update(0);
 }
 update(dt){if(this.disposed)return this.frame;dt=Math.max(0,Math.min(.1,Number.isFinite(dt)?dt:0));this.time=Math.min(EVOLUTION_DURATION,this.time+dt);const w=this.world,f=evolutionFrame(this.time,this.from,this.to,{element:this.element,reduced:this.reduced,aspect:w.camera.aspect});this.frame=f;w.land.visible=this.time<.85&&this.saved.land;w.scene.background.copy(this.saved.background).lerp(this.background.set(f.score.background),ease(this.time/1.0));this.floor.material.color.set(f.score.floor);
  this.oldRoot.visible=f.oldVisible;this.newRoot.visible=f.newVisible;for(const root of[this.oldRoot,this.newRoot]){root.position.y=f.lift;root.scale.setScalar(f.scale);}this.oldRoot.rotation.x=f.pose.pitch;this.oldRoot.rotation.z=f.pose.roll;this.newRoot.rotation.x=f.pose.pitch*.45;this.newRoot.rotation.z=f.pose.roll*.4;this.oldPose.update(dt,f,false);this.newPose.update(dt,f,true);
  const silhouette=f.glow>.4;for(const[o,material]of this.originalMaterials)o.material=silhouette?this.silhouette:material;this.silhouette.color.set(this.palette.color).lerp(this.background.set('#fff5dc'),f.glow*.88);this.light.intensity=f.charge*(f.major?3.8:2.8);this.signature.update(f);
  this.glows.forEach((g,i)=>{g.visible=f.glow>.01&&f.effects>0;g.scale.setScalar(this.size*(i?1.4:2.4)*(1+f.glow));g.material.opacity=f.glow*(this.reduced?.24:i?.22:.48);});
  const bounds={halfWidth:Math.max(this.bounds.halfWidth,this.size*1.15*f.effects),halfDepth:Math.max(this.bounds.halfDepth,this.size*1.15*f.effects),height:this.height+.65*f.effects},camera=fitEvolutionCamera(f,bounds,w.camera.aspect);
  this.eye.set(camera.x,camera.y,camera.z).applyAxisAngle(this.axis,this.root.rotation.y).add(this.root.position);this.target.copy(this.root.position);this.target.y+=f.targetY;if(this.time===0||f.done)w.camera.position.copy(this.eye);else w.camera.position.lerp(this.eye,1-Math.exp(-Math.max(.016,dt)*8));w.target.copy(this.target);w.camera.lookAt(this.target);w.camera.fov=f.fov;w.camera.updateProjectionMatrix();this.onFrame(f);
  if(f.done&&!this.resolved){this.resolved=true;this.resolve({skipped:!!this.skipped});}return f;
 }
 skip(){this.skipped=true;this.time=EVOLUTION_DURATION;this.update(0);}
 dispose({keepNew=false}={}){if(this.disposed)return;this.disposed=true;const w=this.world;this.oldPose.dispose();this.newPose.dispose();for(const[o,material]of this.originalMaterials){o.material=material;const shadow=this.originalShadows.get(o);[o.castShadow,o.receiveShadow]=shadow;}this.oldRoot.remove(this.oldForm.model);this.newRoot.remove(this.newForm.model);w.disposeModel(this.oldForm.model);if(!keepNew)w.disposeModel(this.newForm.model);this.signature.dispose();this.floor.geometry.dispose();this.floor.material.dispose();this.glows.forEach(g=>g.material.dispose());this.texture.dispose();this.silhouette.dispose();w.scene.remove(this.root);w.land.visible=this.saved.land;w.effects.visible=this.saved.effects;w.creature.visible=this.saved.creature;w.rival.visible=this.saved.rival;if(w.sky)w.sky.visible=this.saved.sky;w.scene.background.copy(this.saved.background);w.scene.fog=this.saved.fog;w.renderer.toneMappingExposure=this.saved.exposure;w.viewShift=this.saved.viewShift;const v=this.saved.view;if(v?.enabled)w.camera.setViewOffset(v.fullWidth,v.fullHeight,v.offsetX,v.offsetY,v.width,v.height);else w.camera.clearViewOffset();if(!this.resolved){this.resolved=true;this.resolve({cancelled:true});}}
}
